lucide.createIcons();

document.addEventListener('DOMContentLoaded', () => {
    // Mobile Menu Toggle
    const mobileMenuBtn = document.getElementById('mobile-menu-btn');
    const nav = document.getElementById('nav');

    if (mobileMenuBtn && nav) {
        mobileMenuBtn.addEventListener('click', () => {
            nav.classList.toggle('active');

            // Toggle icon between menu and x
            const icon = mobileMenuBtn.querySelector('i');
            if (nav.classList.contains('active')) {
                icon.setAttribute('data-lucide', 'x');
            } else {
                icon.setAttribute('data-lucide', 'menu');
            }
            lucide.createIcons(); // Re-initialize to update the icon
        });
    }

    // Sticky Header effect on scroll
    const header = document.getElementById('header');

    window.addEventListener('scroll', () => {
        if (window.scrollY > 50) {
            header.classList.add('scrolled');
        } else {
            header.classList.remove('scrolled');
        }
    });

    // Countdown Timer Logic
    const countdownElement = document.getElementById('countdown');

    if (countdownElement) {
        // Set target date to 3 days from now for demo purposes
        const targetDate = new Date();
        targetDate.setDate(targetDate.getDate() + 3);
        targetDate.setHours(targetDate.getHours() + 14);
        targetDate.setMinutes(targetDate.getMinutes() + 45);

        function updateCountdown() {
            const now = new Date().getTime();
            const distance = targetDate.getTime() - now;

            if (distance < 0) {
                countdownElement.innerHTML = "SALE ENDED";
                return;
            }

            const days = Math.floor(distance / (1000 * 60 * 60 * 24));
            const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((distance % (1000 * 60)) / 1000);

            document.getElementById('days').innerText = days.toString().padStart(2, '0');
            document.getElementById('hours').innerText = hours.toString().padStart(2, '0');
            document.getElementById('mins').innerText = minutes.toString().padStart(2, '0');
            document.getElementById('secs').innerText = seconds.toString().padStart(2, '0');
        }

        updateCountdown(); // initial call
        setInterval(updateCountdown, 1000);
    }

    // Simple Add to Cart Interaction
    const addToCartBtns = document.querySelectorAll('.add-to-cart-btn');
    const cartCountElement = document.querySelector('.cart-count');
    let cartCount = parseInt(cartCountElement.innerText);

    addToCartBtns.forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.preventDefault();

            // Visual feedback
            const originalText = this.innerText;
            this.innerText = 'Added!';
            this.style.backgroundColor = '#d33c44'; // Success/Accent color
            this.style.color = '#fff';

            // Update count
            cartCount++;
            cartCountElement.innerText = cartCount;

            // Reset button
            setTimeout(() => {
                this.innerText = originalText;
                this.style.backgroundColor = '';
                this.style.color = '';
            }, 1500);
        });
    });
});
